import{_ as o,l as s,o as e,c as p,v as a,p as l,x as i,d as n,i as d,S as u}from"./chunks/framework.InCnrqk-.js";const v=JSON.parse('{"title":"posted interrupt","description":"","frontmatter":{"title":"posted interrupt","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/interrupt-virtualization.md","filePath":"cs/interrupt-virtualization.md","lastUpdated":1789023840000}'),c={name:"cs/interrupt-virtualization.md"};function h(E,t,P,_,A,f){const r=s("Mermaid");return e(),p("div",null,[t[1]||(t[1]=a('<h1 id="posted-interrupt" tabindex="-1">posted interrupt <a class="header-anchor" href="#posted-interrupt" aria-label="Permalink to &quot;posted interrupt&quot;">​</a></h1><div class="epigraph"><p>Posted interrupt 让宿主把客户中断描述直接写进内存描述符，CPU 在客户模式接受中断而不必每次 VM-exit 到 VMM 注入。</p><footer>—— 据 Intel 对 APICv/Posted Interrupt 的说明；KVM 中断虚拟化文档；[VM-exit](/cs/vmx-vmexit) 为代价先修</footer></div><p><a href="/cs/vfio">VFIO</a> 直通后 IRQ 仍可能打宿主。<a href="/cs/napi">NAPI</a> 在客户里。缺口是 <strong>中断虚拟化</strong>：APIC 虚拟化与 posted。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>传统：物理 IRQ → 宿主 → exit 注入客户。posted：硬件把中断记到 PID 描述符，客户 <code>sti</code> 时递送。缺口：vhost 与 irqfd 已减用户退出；posted 再减内核退出。本课不把 APIC 寄存器图抄完。</p><p><span class="marginnote">ARM GICv4 有类似 LPI 直投。对象是少 exit，不是实时保证。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>启用 APICv → 设备 MSI 指向 posted → 客户在非根模式收中断。对照 <a href="/cs/paravirtualization">半虚拟</a> virtio 中断：仍可走 eventfd。对照 <a href="/cs/preempt-rt">PREEMPT_RT</a>：宿主 RT 与客户中断是两层。</p>',8)),(e(),l(u,null,{default:i(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEV%5B%22%E8%AE%BE%E5%A4%87%20MSI%22%5D%20--%3E%20POST%5B%22Posted%20%E6%8F%8F%E8%BF%B0%E7%AC%A6%22%5D%0A%20%20POST%20--%3E%20G%5B%22%E5%AE%A2%E6%88%B7%E9%9D%9E%E6%A0%B9%E6%94%B6%E4%B8%AD%E6%96%AD%22%5D%0A%20%20OLD%5B%22%E6%97%A0%E8%99%9A%E6%8B%9F%E5%8C%96%22%5D%20--%3E%20EX%5B%22VM-exit%20%E6%B3%A8%E5%85%A5%22%5D%0A"})]),fallback:i(()=>[...t[0]||(t[0]=[n(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>中断虚拟化把「设备吵」从 VMM 热路径拿掉，使直通和 virtio 都能接近裸机 IRQ。不要写成 PIC 历史课。与 <a href="/cs/rss-multiqueue">RSS</a>：客户内多队列仍要自己绑。</p><p>无硬件支持则退回 exit 注入。</p><p>实现上：irqfd 把事件 fd 接到注入路径，已比 ioctl 注入快。posted 再进一步让客户在非根模式收。无 APICv 时每个虚拟中断都可能 exit。 读法上只引用<a href="/cs/vfio">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / Hypervisor」课序里，对象是 <strong>posted interrupt</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 EOI 虚拟化细节。不保证旧 CPU。下一课时钟：客户看见的计时器。</p><p>版本字段会变，课序钉的是机制对象「posted interrupt」，不是某一主线内核的结构体名。 后课默认：客户中断可被 posted 减少 exit。时钟与 TSC 虚拟化，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>posted/APICv 让客户在非根模式收中断。</li><li>目标是砍掉中断引起的 VM-exit。</li><li>时钟虚拟化是下一课。</li><li>出处：Intel SDM APIC virtualization；KVM。</li></ul>',11))])}const I=o(c,[["render",h]]);export{v as __pageData,I as default};
